export function getServiceBySlug(slug: string): ServicePageData | undefined {
  return serviceRegistry[slug];
}

export function getAllServiceSlugs(): string[] {
  return Object.keys(serviceRegistry);
}

export function getCategoryServices(categorySlug: string): ServicePageData[] {
  return Object.values(serviceRegistry).filter(
    (s) => s.categorySlug === categorySlug && s.type === "service"
  );
}

export function getRelatedServices(slugs: string[]): ServicePageData[] {
  return slugs
    .map((s) => serviceRegistry[s])
    .filter((s): s is ServicePageData => s !== undefined);
}
